"<script>const $=id=>document.getElementById(id);let busy=false;function lock(v){busy=v;['pair','cancel','start','restart'].forEach(x=>$(x).disabled=v)}function err(t){$('error').textContent=t||'';$('error').style.display=t?'block':'none'}function pinfmt(n){n=String(Number(n)||0).padStart(8,'0');return n.slice(0,4)+' '+n.slice(4)}function hex(n){n=Number(n)||0;return n?'0x'+(n>>>0).toString(16).toUpperCase():'-'}async function status(){try{const rs=await Promise.all([fetch('/api/remote/status',{cache:'no-store'}),fetch('/service/remote/_root/status',{cache:'no-store'})]);const j=await rs[0].json(),w=await rs[1].json();const online=!!j.service_online,pin=!!w.pairing_pin_ready,done=!!w.pairing_complete,active=!!w.pairing_active;$('worker').textContent=j.worker_pid?('astrorem PID '+j.worker_pid):'OFFLINE';$('rpEnabled').textContent=w.remoteplay_enabled?'HABILITADO':'DESATIVADO';$('rpPort').textContent=w.remoteplay_tcp_9295?'RESPONDENDO':'SEM RESPOSTA';$('pairing').textContent=done?'CONCLUÍDO':(active?'AGUARDANDO DISPOSITIVO':'PARADO');$('pairStat').textContent=String(w.pairing_stat||0);$('pairErr').textContent=hex(w.pairing_error);$('pin').textContent=pin?pinfmt(w.pairing_pin):'--------';$('account').textContent=w.pairing_account_id_ready?('Account ID: '+w.pairing_account_id):'';$('timer').textContent=pin?('Tempo restante: '+String(w.pairing_seconds_left||0)+'s'):'';$('servicePill').textContent=online?'WORKER ONLINE':'WORKER OFFLINE';$('servicePill').className='pill '+(online?'on':'bad');$('phasePill').textContent=(w.phase||j.phase||'idle').replaceAll('_',' ').toUpperCase();if(done){$('screenTitle').textContent='Pareamento concluído ✓';$('screenText').textContent='O PS5 confirmou o registro do dispositivo.'}else if(pin){$('screenTitle').textContent='PIN real do Remote Play';$('screenText').textContent='Use este PIN e o Account ID no cliente que estiver registrando.'}else{$('screenTitle').textContent='Pareamento offline';$('screenText').textContent='Clique em gerar PIN. O Astro habilita o Remote Play e chama libSceRemoteplay diretamente.'}err('')}catch(e){err(String(e.message||e))}}async function act(path){if(busy)return;lock(true);err('');try{const r=await fetch(path,{method:'POST'});const j=await r.json();if(!r.ok){const rc=typeof j.rc==='undefined'?'?':j.rc;throw new Error((j.error||'Falha')+' rc='+rc)}await status()}catch(e){err(String(e.message||e));await status()}finally{lock(false)}}$('pair').onclick=()=>act('/service/remote/_root/pairing/prepare');$('cancel').onclick=()=>act('/service/remote/_root/pairing/cancel');$('start').onclick=()=>act('/api/remote/start');$('restart').onclick=()=>act('/api/remote/restart');status();setInterval(()=>{if(!busy)status()},1000);</script></body></html>";

